import React, { useState } from "react";

const VisualizationSection = () => {
  const [image, setImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [graphMessage, setGraphMessage] = useState("");

  const fetchImage = async (endpoint, graphTitle) => {
    setLoading(true);
    setTitle(graphTitle);

    try {
      const res = await fetch(`http://127.0.0.1:8000/visualize/${endpoint}`);
      const data = await res.json();
      setImage(data.image);
    } catch (err) {
      alert("Error fetching image: " + err);
    }

    setLoading(false);
  };

  return (
    <div
      style={{
        marginTop: "40px",
        padding: "30px",
        background: "linear-gradient(140deg, #a8edea, #fed6e3)",
        borderRadius: "18px",
        boxShadow: "0 5px 20px rgba(0,0,0,0.25)",
      }}
    >
      <h2
        style={{
          textAlign: "center",
          fontSize: "28px",
          marginBottom: "20px",
        }}
      >
        📈 Visualization Dashboard
      </h2>

      {/* Buttons */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-around",
          flexWrap: "wrap",
          gap: "15px",
          marginBottom: "20px",
        }}
      >
        <button
          className="viz-btn"
          onClick={() => fetchImage("roc", "ROC Curve")}
        >
          ROC Curve
        </button>

        <button
          className="viz-btn"
          onClick={() =>
            fetchImage("confusion_heatmap", "Confusion Matrix Heatmap")
          }
        >
          Confusion Heatmap
        </button>

        <button
          className="viz-btn"
          onClick={() =>
            fetchImage("correlation_heatmap", "Correlation Heatmap")
          }
        >
          Correlation Heatmap
        </button>

        <button
          className="viz-btn"
          onClick={() =>
            fetchImage("churn_distribution", "Churn Distribution Chart")
          }
        >
          Churn Distribution
        </button>

        <button
          className="viz-btn"
          onClick={() =>
            fetchImage("feature_importance", "Feature Importance Chart")
          }
        >
          Feature Importance
        </button>
      </div>

      {/* Image Display */}
      <div
        style={{
          textAlign: "center",
          marginTop: "30px",
        }}
      >
        {loading && (
          <div
            style={{
              fontSize: "20px",
              fontFamily: "monospace",
              color: "#333",
            }}
          >
            Loading Visualization...
          </div>
        )}

        {!loading && image && (
          <div>
            <h3 style={{ marginBottom: "15px" }}>{title}</h3>

            <img
              src={`data:image/png;base64,${image}`}
              alt={title}
              style={{
                maxWidth: "95%",
                borderRadius: "12px",
                boxShadow: "0 0 15px rgba(0,0,0,0.3)",
              }}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default VisualizationSection;
